import os
import json
import hashlib
import time
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs, urlencode

STATE_FILE = '/var/lib/cicd-plugin/oauth_states.json'
CONFIG_FILE = '/etc/cicd-plugin/config.json'

def load_config():
    with open(CONFIG_FILE, 'r') as f:
        return json.load(f)

def save_state(state, redirect_uri):
    """Persist OAuth state to validate on callback"""
    try:
        with open(STATE_FILE, 'r') as f:
            states = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        states = {}
    states[state] = {'redirect_uri': redirect_uri, 'ts': time.time()}
    with open(STATE_FILE, 'w') as f:
        json.dump(states, f)

def load_state(state):
    try:
        with open(STATE_FILE, 'r') as f:
            states = json.load(f)
        return states.get(state)
    except (FileNotFoundError, json.JSONDecodeError):
        return None

def generate_state():
    return hashlib.sha256(os.urandom(32)).hexdigest()

class OAuthHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        config = load_config()
        parsed = urlparse(self.path)
        params = parse_qs(parsed.query)

        if parsed.path == '/oauth/authorize':
            self.handle_authorize(config, params)
        elif parsed.path == '/oauth/callback':
            self.handle_callback(config, params)
        else:
            self.send_error(404)

    def handle_authorize(self, config, params):
        redirect_uri = params.get('redirect_uri', [config['default_redirect']])[0]

        # VULNERABILITY: Only checks if redirect_uri starts with allowed domain
        # but does not validate full URL structure, allowing path traversal
        # and open redirect via: https://ci.internal.corp.com.evil.com/steal
        allowed_prefix = config.get('allowed_redirect_prefix', 'https://ci.internal.corp.com')

        if not redirect_uri.startswith(allowed_prefix):
            self.send_error(403, 'Invalid redirect_uri')
            return

        state = generate_state()
        save_state(state, redirect_uri)

        auth_params = urlencode({
            'client_id': config['client_id'],
            'redirect_uri': redirect_uri,
            'state': state,
            'response_type': 'code',
            'scope': 'repo:read pipeline:trigger'
        })
        auth_url = f"{config['oauth_provider']}/authorize?{auth_params}"

        self.send_response(302)
        self.send_header('Location', auth_url)
        self.end_headers()

    def handle_callback(self, config, params):
        code = params.get('code', [None])[0]
        state = params.get('state', [None])[0]

        if not code or not state:
            self.send_error(400, 'Missing code or state')
            return

        state_data = load_state(state)
        if not state_data:
            self.send_error(403, 'Invalid or expired state')
            return

        # Exchange code for token (simplified)
        redirect_uri = state_data['redirect_uri']

        # Redirect user back with the authorization code
        final_url = f"{redirect_uri}?code={code}&state={state}"
        self.send_response(302)
        self.send_header('Location', final_url)
        self.end_headers()

def main():
    config = load_config()
    port = config.get('port', 8080)
    server = HTTPServer(('0.0.0.0', port), OAuthHandler)
    print(f'CI/CD OAuth plugin listening on port {port}')
    server.serve_forever()

if __name__ == '__main__':
    main()
